result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/server.py", "content": """"Line-based chat server over TCP, Python stdlib only."""

import socket
import threading


class ClientSession:
    """State + socket for one connected client."""

    def __init__(self, conn: socket.socket, addr):
        self.conn = conn
        self.addr = addr
        self.nick = None
        self.rooms = set()
        self.alive = True

    def send_line(self, line: str) -> None:
        try:
            self.conn.sendall((line + "\n").encode("utf-8"))
        except OSError:
            self.alive = False


class ChatServer:
    def __init__(self, host="127.0.0.1", port=0):
        self._host = host
        self._listen_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._listen_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._listen_sock.bind((host, port))
        self.port = self._listen_sock.getsockname()[1]
        self._listen_sock.listen(16)

        self._lock = threading.Lock()
        # room name -> set of ClientSession
        self.rooms = {}
        # nick -> ClientSession
        self.clients_by_nick = {}
        self._sessions = set()

        self._shutdown = threading.Event()
        self._thread = None

    # ---- lifecycle -------------------------------------------------

    def start(self):
        self._thread = threading.Thread(target=self.serve_forever, daemon=True)
        self._thread.start()

    def serve_forever(self):
        self._listen_sock.settimeout(0.2)
        while not self._shutdown.is_set():
            try:
                conn, addr = self._listen_sock.accept()
            except socket.timeout:
                continue
            except OSError:
                break
            session = ClientSession(conn, addr)
            with self._lock:
                self._sessions.add(session)
            t = threading.Thread(target=self._handle_client, args=(session,), daemon=True)
            t.start()

    def stop(self):
        self._shutdown.set()
        try:
            self._listen_sock.close()
        except OSError:
            pass
        if self._thread is not None:
            self._thread.join(timeout=2)
        with self._lock:
            sessions = list(self._sessions)
        for s in sessions:
            s.alive = False
            try:
                s.conn.close()
            except OSError:
                pass

    # ---- protocol ---------------------------------------------------

    def _handle_client(self, session: ClientSession):
        buf = b""
        try:
            session.conn.settimeout(None)
            while session.alive and not self._shutdown.is_set():
                while b"\n" not in buf:
                    chunk = session.conn.recv(4096)
                    if not chunk:
                        return  # peer disconnected
                    buf += chunk
                line, buf = buf.split(b"\n", 1)
                text = line.decode("utf-8", errors="replace").strip("\r")
                if text:
                    self._dispatch(session, text)
        except OSError:
            pass
        finally:
            self._cleanup(session)

    def _dispatch(self, session: ClientSession, line: str):
        parts = line.split(" ", 2)
        cmd = parts[0].upper()

        if cmd == "NICK" and len(parts) == 2:
            nick = parts[1]
            if not nick:
                session.send_line("ERR bad command")
                return
            with self._lock:
                if nick in self.clients_by_nick:
                    session.send_line("ERR nick taken")
                    return
                if session.nick is not None:
                    del self.clients_by_nick[session.nick]
                session.nick = nick
                self.clients_by_nick[nick] = session
            session.send_line("OK")
            return

        if cmd == "JOIN" and len(parts) == 2:
            if session.nick is None:
                session.send_line("ERR bad command")
                return
            room = parts[1]
            if not room:
                session.send_line("ERR bad command")
                return
            with self._lock:
                self.rooms.setdefault(room, set()).add(session)
                session.rooms.add(room)
            session.send_line("OK")
            return

        if cmd == "MSG":
            if session.nick is None:
                session.send_line("ERR bad command")
                return
            rest = parts[1] if len(parts) > 1 else ""
            if " " in rest:
                room, message = rest.split(" ", 1)
            else:
                room, message = rest, ""
            if not room:
                session.send_line("ERR bad command")
                return
            self._broadcast(room, f"FROM {session.nick} {room} {message}")
            return

        if cmd == "PART" and len(parts) == 2:
            room = parts[1]
            with self._lock:
                members = self.rooms.get(room)
                if members:
                    members.discard(session)
                    if not members:
                        del self.rooms[room]
                session.rooms.discard(room)
            session.send_line("OK")
            return

        if cmd == "QUIT":
            session.send_line("OK")
            session.alive = False
            return

        session.send_line("ERR bad command")

    def _broadcast(self, room: str, line: str):
        with self._lock:
            members = list(self.rooms.get(room, ()))
        for member in members:
            member.send_line(line)

    def _cleanup(self, session: ClientSession):
        with self._lock:
            self._sessions.discard(session)
            if session.nick is not None:
                if self.clients_by_nick.get(session.nick) is session:
                    del self.clients_by_nick[session.nick]
            for room in session.rooms:
                members = self.rooms.get(room)
                if members is not None:
                    members.discard(session)
                    if not members:
                        del self.rooms[room]
            session.rooms.clear()
            session.alive = False
        try:
            session.conn.close()
        except OSError:
            pass


def main():
    server = ChatServer()
    print(server.port, flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.stop()


if __name__ == "__main__":
    main()
